// Integrated v08. All numeric management rules below are editable trial values.
const BALANCE={startFunds:3000,facilityPrice:1000,maintenance:150,baseReward:350,runReward:80,winReward:600,hireFactor:35,trainingFactor:110,salaryFactor:4,contractGames:5,ticketBase:10,pitchCost:1.2,swingCost:.8,powerCost:1.6,runCost:.025,fatigueFloor:.35,staminaCap:100,fanEventChance:.32};
const BALANCE_LABELS={startFunds:'새 구단 시작 자금',facilityPrice:'기본 시설 건설비',maintenance:'시설당 경기 유지비',baseReward:'경기 완료 자금',runReward:'득점당 자금',winReward:'승리 추가 자금',hireFactor:'영입 계수 · 평균² ÷50에 곱함',trainingFactor:'성장 구간당 기본 비용',salaryFactor:'급여 계수 · 평균² ÷50에 곱함',contractGames:'계약 경기 수',ticketBase:'기준 입장료',pitchCost:'투구 체력 소모',swingCost:'일반 스윙 체력 소모',powerCost:'풀스윙 체력 소모',runCost:'이동 거리당 체력 소모',fatigueFloor:'최저 체력의 능력 비율',staminaCap:'시험 스태미나 성장 한도',fanEventChance:'경기 후 팬 사건 확률'};
STATS.stamina='스태미나';KEYS.push('stamina');
function balance(t=team()){return {...BALANCE,...t?.balance};}
function meanAbility(p){return KEYS.filter(k=>k!=='stamina').reduce((s,k)=>s+p.a[k],0)/9;}
function abilityPrice(p){return meanAbility(p)**2/50;}
function adjustEconomy(t){if(!t||t.economyVersion===9||t.match&&!t.match.done)return;
 t.balance={...BALANCE,...t.balance,maintenance:150,hireFactor:35,trainingFactor:110,salaryFactor:4};
 t.players.forEach(p=>p.salary=Math.max(3,Math.round(abilityPrice(p)*t.balance.salaryFactor)));
 (t.market||[]).forEach(p=>{p.salary=Math.max(3,Math.round(abilityPrice(p)*t.balance.salaryFactor));p.price=Math.round(abilityPrice(p)*t.balance.hireFactor);});
 t.economyVersion=9;t.economyNotice=true;
}
function operatingBudget(t){const salary=t.players.reduce((n,p)=>n+p.salary,0),maintenance=t.facilities.length*balance(t).maintenance;return {salary,maintenance,total:salary+maintenance};}
function budgetHTML(t,compact=false){const b=balance(t),o=operatingBudget(t),gate=attendance(t)*t.ticket,shops=attendance(t)*t.facilities.filter(x=>['goods','restaurant','store'].includes(x)).length,loss=b.baseReward+3*b.runReward+(gate+shops)/2-o.total;
if(compact)return '<section class="panel operating-budget home-budget"><h3>다음 경기 운영비</h3><div class="row between"><span>선수 '+t.players.length+'명 급여</span><b>'+money(o.salary)+'</b></div><div class="row between"><span>시설 '+t.facilities.length+'개 유지비</span><b>'+money(o.maintenance)+'</b></div><div class="row between budget-total"><strong>고정 지출</strong><strong class="bad">'+money(o.total)+'</strong></div><p class="budget-forecast">예상 손익 · 패배 '+(loss>=0?'+':'')+money(loss)+'<br>승리 '+(loss+b.winReward>=0?'+':'')+money(loss+b.winReward)+'</p><p class="budget-note">홈·원정 반반, 경기당 3득점 가정<br>관중·득점·시설·선수단에 따라 달라집니다.</p><div class="row between"><span>미지급금 별도</span><b>'+money(t.debt)+'</b></div>'+(t.funds<o.total?'<p class="bad budget-warning">운영비가 부족합니다. 추가 투자 전 결산을 확인하세요.</p>':'')+'</section>';
return '<section class="panel settings-extra"><h3>다음 경기 운영비</h3><div class="row between"><span>선수 '+t.players.length+'명 급여</span><b>'+money(o.salary)+'</b></div><div class="row between"><span>시설 '+t.facilities.length+'개 유지비</span><b>'+money(o.maintenance)+'</b></div><div class="row between"><strong>매 경기 고정 지출</strong><strong class="bad">'+money(o.total)+'</strong></div><p class="muted-note">홈·원정 반반, 경기당 3득점 가정 · 경기당 예상 손익<br>패배 '+(loss>=0?'+':'')+money(loss)+' / 승리 '+(loss+b.winReward>=0?'+':'')+money(loss+b.winReward)+'<br>관중·득점·시설·선수단에 따라 달라집니다. 현재 미지급금은 별도 '+money(t.debt)+'.</p>'+(t.funds<o.total?'<p class="bad">보유 자금이 1경기 운영비보다 적습니다. 추가 투자 전 결산을 확인하세요.</p>':'')+'</section>';
}
function appearance(){return {version:12,body:randomInt(0,5),skin:randomInt(0,5),hairColor:randomInt(1,6),eyeColor:randomInt(0,5),parts:{hair:Math.random()<.3?-1:randomInt(0,6),beard:Math.random()<.65?-1:randomInt(0,4),wear:Math.random()<.7?-1:randomInt(0,5),black:Math.random()<.65?-1:randomInt(0,2),eyes:randomInt(0,5),nose:randomInt(0,5),brows:randomInt(0,5),mouth:randomInt(0,5)}};}
function migrateAppearance(a){if(!a)return;if(!a.parts)a.parts={};const p=a.parts;if(a.version!==12){if(p.beard>=0)p.beard=[4,0,1,2,3][p.beard]??p.beard;if(p.wear>=0)p.wear=[0,1,4,5][p.wear]??p.wear;if(p.brows>=0)p.brows=[0,1,4,2,3,5,5][p.brows]??p.brows;a.version=12;}p.black??=-1;}

function enrich(p){p.appearance??=appearance();migrateAppearance(p.appearance);p.a.stamina??=randomInt(40,60);p.energy??=p.a.stamina;p.loyalty??=randomInt(45,70);p.fans??=randomInt(15,85);p.salary??=Math.max(3,Math.round(abilityPrice(p)*balance().salaryFactor));p.contract??=balance().contractGames;p.lowOffers??=0;return p;}
const oldPlayer=player;player=function(...args){const p=oldPlayer(...args);p.a.stamina=randomInt(40,args[2]?80:60);return enrich(p);};
function ensureClub(t){if(!t)return;t.funds??=BALANCE.startFunds;t.balance??={...BALANCE};t.facilities??=[];t.stadium??=1;t.ticket??=10;t.debt??=0;t.ledger??=[];t.news??=[];t.departed??=[];t.market??=[];t.players.forEach(enrich);if(t.match?.opp){t.match.opp.players.forEach(enrich);t.match.used??=t.lineup.map(x=>x.id);t.match.subs??=[];}t.coins=0;t.trophies=t.w;adjustEconomy(t);}
const oldNewTeam=newTeam;newTeam=function(...args){const t=oldNewTeam(...args);ensureClub(t);t.players.forEach((p,i)=>p.appearance.body=i%6);return t;};
const oldInitial=ensureInitialRoster;ensureInitialRoster=function(t){const empty=!t.players.length;oldInitial(t);ensureClub(t);if(empty)t.players.forEach((p,i)=>p.appearance.body=i%6);};
const originalGo=go;go=function(where){if(activeGame&&needsSetup(team())&&['market','facilities','finance','news'].includes(where)){toast('먼저 시작 선수 12명의 이름·등번호와 라인업을 정해 주세요.');where='setup';}originalGo(where);};
ensurePlayerLooks=function(t){if(!t?.players)return;t.players.forEach(enrich);if(t.match?.opp)ensurePlayerLooks(t.match.opp);};
const oldValidate=validateTeam;validateTeam=function(t){t.players.forEach(p=>migrateAppearance(p.appearance));oldValidate(t);if(!Number.isFinite(t.funds)||t.funds<0||!Array.isArray(t.facilities)||!Number.isInteger(t.stadium)||t.stadium<1||t.stadium>5||!Number.isFinite(t.debt)||t.debt<0)throw Error('v08 구단 자료가 아닙니다. 이전 저장 원본은 이전 버전에서 열어주세요.');for(const p of t.players){const a=p.appearance;if(!a||!Number.isInteger(a.body)||a.body<0||a.body>5||!Number.isFinite(p.energy)||p.energy<0||p.energy>p.a.stamina||!Number.isFinite(p.salary)||p.salary<0||!Number.isInteger(p.contract)||p.contract<0||!Number.isFinite(p.loyalty)||p.loyalty<0||p.loyalty>100||!Number.isFinite(p.fans)||p.fans<0)throw Error('선수 체력·외형·계약 자료 오류');for(const k of Object.keys(CharacterRenderer.names)){const v=a.parts?.[k];if(!Number.isInteger(v)||v< -1||v>=CharacterRenderer.variants[k].length)throw Error('외형 파츠 자료 오류');}}for(const [k,v]of Object.entries(t.balance||{}))if(!(k in BALANCE)||!Number.isFinite(v)||v<0||v>100000)throw Error('시험 설정 오류');};
const FACILITIES=[['bat','타격 훈련실','컨택 · 파워 · 선구안 성장',['contact','power','eye'],'훈련'],['field','수비 훈련실','야구센스 · 포구 · 송구 성장',['sense','catch','throw'],'훈련'],['pitch','투수 훈련실','구속 · 제구 성장',['velocity','control'],'훈련'],['run','달리기장','주력 성장',['speed'],'훈련'],['fitness','체력 훈련실','스태미나 성장',['stamina'],'훈련'],['shower','샤워실','경기 후 애정도 +1',[],'복지'],['locker','탈의실','경기 후 애정도 +1',[],'복지'],['massage','마사지실','경기 후 애정도 +1',[],'복지'],['sleep','수면실','경기 후 애정도 +1',[],'복지'],['food','선수 식당','경기 후 애정도 +1',[],'복지'],['goods','유니폼 · 굿즈 매장','홈 관중 1명당 추가 수입 1,000원',[],'수익'],['restaurant','구장 음식점','홈 관중 1명당 추가 수입 1,000원',[],'수익'],['store','편의점','홈 관중 1명당 추가 수입 1,000원',[],'수익'],['fans','팬 만남 광장','경기 후 모든 선수 팬 +2',[],'팬']];
const WON_PER_UNIT=10000,TICKET_WON_PER_UNIT=1000,SPECTATORS_PER_UNIT=10;
const wonValue=n=>Math.round(n*WON_PER_UNIT);
function formatWon(value){const n=Math.abs(Math.round(value)),sign=value<0?'-':'',eok=Math.floor(n/100000000),man=Math.floor(n%100000000/10000),won=n%10000,parts=[];if(eok)parts.push(eok.toLocaleString('ko-KR')+'억');if(man)parts.push(man.toLocaleString('ko-KR')+'만');if(won)parts.push(won.toLocaleString('ko-KR'));return sign+(parts.length?parts.join(' ')+' 원':'0원');}
const money=n=>formatWon(wonValue(n));
const spectators=n=>Math.round(n*SPECTATORS_PER_UNIT).toLocaleString('ko-KR');
const ticketInput=n=>n*TICKET_WON_PER_UNIT;
const ticketFromInput=n=>Number(n)/TICKET_WON_PER_UNIT;
const salaryFromInput=n=>Number(n)/WON_PER_UNIT;
function balanceUnit(k){return k==='ticketBase'?TICKET_WON_PER_UNIT:['startFunds','facilityPrice','maintenance','baseReward','runReward','winReward','hireFactor','trainingFactor','salaryFactor'].includes(k)?WON_PER_UNIT:1;}

const live=t=>!!(t?.match&&!t.match.done);
function ledger(t,label,amount){t.ledger.unshift({at:Date.now(),label,amount});t.ledger=t.ledger.slice(0,150);}
function spend(t,price,label){if(!Number.isFinite(price)||price<0||t.funds<price)return false;t.funds-=price;ledger(t,label,-price);return true;}
function gain(t,amount,label){if(amount<0||!Number.isFinite(amount))throw Error('잘못된 수입');t.funds+=amount;ledger(t,label,amount);}
function news(t,title,text){t.news.unshift({at:Date.now(),title,text});t.news=t.news.slice(0,50);}
function attendance(t){const b=balance(t),cap=t.stadium*200,pop=t.players.reduce((s,p)=>s+p.fans,0)*.3+80;return Math.round(clamp(pop*(b.ticketBase/Math.max(1,t.ticket))**1.8,0,cap));}
function costGrowth(p,k){const b=balance();return p.a[k]>=(k==='stamina'?b.staminaCap:100)?0:cost(p.a[k])*b.trainingFactor;}
function trainingFacility(k){return FACILITIES.find(f=>f[3].includes(k));}
function energyHTML(p){const pct=Math.round(100*p.energy/p.a.stamina);return '<span class="energy"><i style="width:'+pct+'%;background:'+(pct<25?'#ff736f':'#68d2a4')+'"></i></span><small>체력 '+Math.round(p.energy)+' / '+p.a.stamina+(pct<25?' · 능력 저하':'')+'</small>';}
const MARKET_REFRESH_COST=100;
function createMarketCandidates(t){return Array.from({length:3},()=>{const p=player(false,t.players.map(x=>x.number));p.price=Math.round(abilityPrice(p)*balance(t).hireFactor);return p;});}
function refreshMarket(t){const round=t.w+t.l+t.d;if(t.marketRound===round)return;const candidates=createMarketCandidates(t);t.marketRound=round;t.market=candidates;save();}
function rerollMarket(t){if(live(t)||!Number.isFinite(t.funds)||t.funds<MARKET_REFRESH_COST)return false;const candidates=createMarketCandidates(t);if(!spend(t,MARKET_REFRESH_COST,'영입 후보 새로 찾기'))return false;t.market=candidates;t.marketRound=t.w+t.l+t.d;return true;}
function preGameEconomy(t){ensureClub(t);if(t.players.some(p=>p.contract===0)){toast('계약이 끝난 선수의 연봉을 재협상해 주세요.');go('finance');return false;}return true;}
const oldStart=startMatch;startMatch=function(){const t=team();if(!needsSetup(t)&&!live(t)&&!preGameEconomy(t))return;const before=t.match?.id;oldStart();if(t.match?.id!==before){for(const tm of [t,t.match.opp])tm.players.forEach(p=>p.energy=p.a.stamina);t.match.used=t.lineup.map(x=>x.id);t.match.subs=[];save();render();}};
let fatigueSnapshot=null;
function restoreAbilities(){if(!fatigueSnapshot)return;for(const [p,a]of fatigueSnapshot)p.a=a;fatigueSnapshot=null;}
function effective(p,k){if(k==='stamina')return p.a[k];const ratio=clamp(p.energy/p.a.stamina,0,1),mult=ratio>=.5?1:balance().fatigueFloor+(1-balance().fatigueFloor)*(ratio/.5);return Math.max(1,Math.round(p.a[k]*mult));}
const originalBuildMotion=buildMotion;buildMotion=function(m,e){originalBuildMotion(m,e);for(const move of e.fieldMoves){if(move.knots||e.bh)continue;const p=ply(tside(m,1-e.attack),move.id),dist=Math.hypot(move.to[0]-move.from[0],move.to[1]-move.from[1]);move.end=clamp(.22+dist/(70+p.a.speed*1.2)*.28,.29,.85);}};
const oldResolve=resolvePitch;resolvePitch=function(m){const t=team();fatigueSnapshot=[t,m.opp].flatMap(tm=>tm.players.map(p=>[p,p.a]));for(const [p,a]of fatigueSnapshot)p.a=Object.fromEntries(KEYS.map(k=>[k,k==='stamina'?a[k]:effective(p,k)]));let e;try{e=oldResolve(m);}finally{restoreAbilities();}const b=balance(t),at=tside(m,e.attack),df=tside(m,1-e.attack),deduct=(p,n)=>{if(p)p.energy=Math.max(0,p.energy-n);};if(e.pitchThrown)deduct(ply(df,e.pitcher),b.pitchCost);if(e.swing)deduct(ply(at,e.batter),e.inputCommand==='power'?b.powerCost:b.swingCost);for(const mv of e.moves){let d=0;for(let i=1;i<mv.points.length;i++)d+=Math.hypot(mv.points[i][0]-mv.points[i-1][0],mv.points[i][1]-mv.points[i-1][1]);deduct(ply(at,mv.id),d*b.runCost*.22);}for(const mv of e.fieldMoves)deduct(ply(df,mv.id),Math.hypot(mv.to[0]-mv.from[0],mv.to[1]-mv.from[1])*b.runCost);save();return e;};
reward=function(m){if(m.rewarded)return;const t=team(),b=balance(t);m.rewarded=true;const win=m.score[0]>m.score[1];if(win)t.w++;else if(m.score[0]<m.score[1])t.l++;else t.d++;t.trophies=t.w;t.offer=null;m.result=win?'승리':m.score[0]===m.score[1]?'무승부':'패배';const crowd=attendance(t),ticket=m.home===0?crowd*t.ticket:0,stores=m.home===0?crowd*t.facilities.filter(id=>['goods','restaurant','store'].includes(id)).length:0,reward=b.baseReward+m.score[0]*b.runReward+(win?b.winReward:0),salary=t.players.reduce((s,p)=>s+p.salary,0),maint=t.facilities.length*b.maintenance,total=reward+ticket+stores;
gain(t,total,'경기 수입 · '+gameResultLabel(m));const due=salary+maint+t.debt,paid=Math.min(t.funds,due);spend(t,paid,'급여·시설·미지급금 결산');t.debt=due-paid;m.reward=reward;m.finance={reward,ticket,stores,crowd,salary,maintenance:maint,paid,debt:t.debt,net:total-paid};
const welfare=t.facilities.filter(id=>FACILITIES.find(f=>f[0]===id)?.[4]==='복지').length;for(const p of t.players){settleContract26(t,p,m,welfare);p.fans=Math.max(0,p.fans+(win?3:0)+(t.facilities.includes('fans')?2:0));}if(t.debt)news(t,'급여·유지비 일부 미지급','미지급금 '+money(t.debt)+'가 다음 결산으로 이어집니다. 선수 애정도가 8 감소했습니다.');
if(r(m)<b.fanEventChance)rollClubEvent(t,m);t.market=[];
t.history.unshift({id:m.id,opp:m.opp.name,score:m.score.slice(),result:m.result,mercy:clone(m.mercy||null),coins:0,funds:reward,finance:clone(m.finance),bh:m.bh[0],pitches:m.pitches,events:clone(m.events),checks:clone(m.checks),innings:clone(m.innings),home:m.home,hits:m.hits.slice(),errors:m.errors.slice(),boneheads:m.bh.slice(),skipped:!!m.skipped,recap:clone(m.recap||{box:{},highlights:[],events:0}),subs:clone(m.subs||[]),at:Date.now()});t.history=t.history.slice(0,20);departUnhappy26(t);};

