function charFrame(p,tm,mode='motion',row=1,col=0){const a=enrich(p).appearance,key=[p.id,p.number,tm.primary,tm.secondary,mode,row,col,JSON.stringify(a)].join('|');if(charCache.has(key))return charCache.get(key);
const out=CharacterRenderer.render({...a,mode,row,col,palette:{primary:COLORS[tm.primary][1],secondary:COLORS[tm.secondary][1],skin:SKINS[a.skin]}}),cv=canvasNew(out.canvas.width,out.canvas.height),g=cv.getContext('2d');g.imageSmoothingEnabled=false;g.drawImage(out.canvas,0,0);const f=out.face;
if(mode==='detail'){g.fillStyle=COLORS[tm.secondary][1];g.textAlign='center';g.font='36px NeoDunggeunmo';g.fillText(String(p.number),580,570);}
const stand=LAB_DATA.bodies[a.body].motion.frames[1][0].rect,result={...out,canvas:cv,body:a.body,standHeight:stand[3]-stand[1],anchorX:out.foot[0],anchorY:out.foot[1]};if(charCache.size>450)charCache.clear();charCache.set(key,result);return result;}

const oldSprite=sprite;
sprite=function(c,x,y,scale,tm,number=0,role='player',pose='idle',tick=0,id='',flip=false){if(role!=='player'||!charsReady)return oldSprite(c,x,y,scale,tm,number,role,pose,tick,id,flip);const p=tm.players?.find(p=>p.id===id)||tm.market?.find(p=>p.id===id)||tm.players?.find(p=>p.number===number)||demoPlayer;let row=1,col=0;const e=anim?.e,pt=anim?playProgress(anim.elapsed/anim.duration):0;
if(pose==='run'){row=3;col=2+Math.floor(tick/(220-effective(p,'speed')))%2;}else if(pose==='bat'){row=0;col=0;}else if(pose==='swing'){row=0;col=pt<.23?2:e?.inputCommand==='power'?4:3;}else if(pose==='pitch'){row=1;col=Math.min(4,Math.floor(pt/.22*5));flip=true;}else if(pose==='throw'){row=2;col=4;}else if(['glove','catcher'].includes(pose)){row=2;col=1;}else if(pose==='catch'){row=4;col=0;}else if(pose==='slide'){row=4;col=3;}else if(pose==='sad'){row=5;col=5;}else if(pose==='confused'){row=5;col=3;}else if(pose==='celebrate'){row=4;col=0;}
if(['bat','swing'].includes(pose))flip=p.hand==='좌타';const a=charFrame(p,tm,'motion',row,col),height=[45,57,50,52,49,57][a.body]*scale,s=height/a.standHeight;c.save();c.translate(Math.round(x),Math.round(y));c.fillStyle='#06241f65';c.beginPath();c.ellipse(0,2,12*scale,3*scale,0,0,Math.PI*2);c.fill();if(flip)c.scale(-1,1);c.imageSmoothingEnabled=false;c.drawImage(a.canvas,Math.round(-a.anchorX*s),Math.round(-a.anchorY*s),Math.round(a.canvas.width*s),Math.round(a.canvas.height*s));c.restore();};
