growthArtworkHTML=function(t){const p=ply(t,selection)||t.players[0];selection=p.id;return head('선수 성장','훈련시설을 갖춘 뒤, 자금으로 능력치를 올립니다.')+'<section class="scene-frame scene-training growth-layout"><div class="growth-player"><select id="growthPlayer">'+t.players.map(x=>'<option value="'+x.id+'" '+(p.id===x.id?'selected':'')+'>'+esc(x.name)+' #'+x.number+'</option>').join('')+'</select><canvas id="practiceCast" width="500" height="350"></canvas></div><section class="panel stack"><h2>'+esc(p.name)+' #'+p.number+'</h2>'+KEYS.map(k=>{const f=trainingFacility(k),price=costGrowth(p,k),has=t.facilities.includes(f[0]);return '<div class="trainingrow"><span>'+STATS[k]+'<small class="muted" style="display:block">'+(has?f[1]:f[1]+' 필요')+'</small></span><b>'+p.a[k]+' → '+(price?p.a[k]+1:p.a[k])+'</b><button class="small primary" data-v8="train" data-stat="'+k+'" '+(live(t)||!has||!price||t.funds<price?'disabled':'')+'>'+(price?''+money(price):'최대')+'</button></div>';}).join('')+'<p class="fund">보유 자금 '+money(t.funds)+'</p><button data-go="facilities">훈련시설 확인</button></section></section>';};
