function entranceStage(ms){return ms<2100?0:ms<4100?1:2;}
function entranceOrder(m){return m?.home===0?{label:'우리 팀 후공 · 1회 말 공격',detail:'1회 초에는 수비부터 시작합니다.'}:{label:'우리 팀 선공 · 1회 초 공격',detail:'1회 초에 먼저 타석에 들어섭니다.'};}
