 if(pose==='throw')return[2,t<.59?2:t<.64?3:4];
 if(pose==='glove'||pose==='catcher')return[2,1];
 if(pose==='catch'||pose==='celebrate')return[4,0];
 if(pose==='slide')return[4,3];
 if(pose==='sad')return[5,5];
