  const prior=e.before.score[0]-e.before.score[1],now=e.after.score[0]-e.after.score[1];
  return 'f23-'+(own?(now===0?'tie':now>0?(prior<=0?'lead':'extend'):'chase'):(now===0?'awayTie':now<0?(prior>=0?'awayLead':'awayExtend'):'awayChase'));
